const [{ json }] = items;
const tenantId = json.tenant_id;
const domain = (json.domain || '').trim();

if (!tenantId || !domain) {
  throw new Error('tenant_id and domain are required');
}

const normalizeProtocol = (value) => {
  const trimmed = value.replace(/\s+/g, '').replace(/\/+$/, '');
  if (!/^https?:\/\//i.test(trimmed)) {
    return `https://${trimmed}`;
  }
  return trimmed.replace(/^http:\/\//i, 'https://');
};

const normalizedDomain = normalizeProtocol(domain);

$flow.set('tenant_id', tenantId);
$flow.set('domain', normalizedDomain);

return [
  {
    json: {
      tenant_id: tenantId,
      domain: normalizedDomain,
    },
  },
];

const tenantId = $flow.get('tenant_id');
const pages = items[0].json?.result?.pages || items[0].json?.pages || [];

const normalized = [];

for (const page of pages) {
  if (!page) continue;
  const text = page.text || page.content || '';
  if (!text.trim()) continue;

  normalized.push({
    tenant_id: tenantId,
    source_url: page.url || page.source_url || '',
    title: page.title || page.url || 'Untitled Page',
    text,
  });
}

return normalized.map((entry) => ({ json: entry }));

const chunkSize = 1200;
const overlap = 200;
const chunks = [];

for (const item of items) {
  const { tenant_id, source_url, title, text } = item.json;
  if (!text) continue;

  const cleaned = text.replace(/\s+/g, ' ').trim();
  if (!cleaned) continue;

  let index = 0;
  for (let start = 0; start < cleaned.length; start += chunkSize - overlap) {
    const end = Math.min(cleaned.length, start + chunkSize);
    const content = cleaned.slice(start, end);
    chunks.push({
      json: {
        tenant_id,
        source_url,
        title,
        content,
        chunk_index: index,
      },
    });
    if (end === cleaned.length) break;
    index += 1;
  }
}

return chunks;

return items.map((item) => {
  const { tenant_id, doc_id, source_url, title, content, chunk_index } = item.json;
  return {
    json: {
      tenant_id,
      doc_id,
      source_url,
      title,
      content,
      chunk_index,
      embeddingRequest: {
        model: 'text-embedding-3-small',
        input: content,
      },
    },
  };
});

const results = [];

for (const item of items) {
  const embedding = item.json.data?.[0]?.embedding;
  if (!Array.isArray(embedding) || embedding.length === 0) {
    throw new Error('OpenAI embedding response is missing data');
  }

  const record = {
    tenant_id: item.json.tenant_id,
    doc_id: item.json.doc_id,
    chunk_index: item.json.chunk_index,
    source_url: item.json.source_url,
    title: item.json.title,
    embedding,
    embedding_literal: `[${embedding.join(',')}]`,
  };

  results.push({ json: record });
}

return results;

const tenantId = $flow.get('tenant_id');
const summary = {
  tenant_id: tenantId,
  chunks_processed: items.length,
  sources: [],
};

const seen = new Set();

for (const item of items) {
  const { source_url, title } = item.json;
  if (source_url && !seen.has(source_url)) {
    seen.add(source_url);
    summary.sources.push({
      source_url,
      title,
    });
  }
}

return [
  {
    json: {
      status: 'success',
      ...summary,
    },
  },
];
